/**
 * Контракт между платформой и играми. Имена фиксированы: на них опираются все игры.
 * Игра импортирует из платформы только `platform/sdk/*`.
 */

/** Генератор случайных чисел. `next()` возвращает число в [0, 1). Передаётся игре платформой. */
export interface Rng {
  next(): number;
}

/**
 * Результат шага игры.
 * - `continue` — раунд продолжается, нужен следующий ход;
 * - `finished` — раунд окончен, `payout` — полная сумма к зачислению (0 при проигрыше).
 */
export type Step<S> =
  | { status: 'continue'; state: S }
  | { status: 'finished'; state: S; payout: number };

/**
 * Серверный модуль игры. Платформа вызывает его внутри раунда: списывает ставку до `start`
 * и зачисляет `payout` после шага со статусом `finished`. Игра не знает о кошельке и балансе.
 *
 * Состояние `S` и параметры `P` должны сериализоваться в JSON: платформа хранит их на диске.
 */
export interface GameModule<P = any, S = any, A = any> {
  /** Идентификатор игры, совпадает с `id` в `manifest.json`. */
  id: string;
  /** Проверяет и нормализует параметры раунда. Бросает `GameError('INVALID_PARAMS')`. */
  validateParams(params: unknown): P;
  /** Начинает раунд (ставка уже списана). */
  start(ctx: { bet: number; params: P; rng: Rng }): Step<S>;
  /** Ход игрока. Бросает `GameError('INVALID_ACTION')` на недопустимое действие. */
  action(ctx: { bet: number; params: P; state: S; action: A; rng: Rng }): Step<S>;
  /** Что можно показать клиенту. До конца раунда (`finished = false`) скрытое не раскрывается. */
  publicView(state: S, finished: boolean): unknown;
}

/** Ошибка игры с кодом (`INVALID_PARAMS`, `INVALID_ACTION`). Платформа передаёт код клиенту. */
export class GameError extends Error {
  /** Код ошибки. */
  code: string;

  /**
   * @param code код ошибки, например `INVALID_PARAMS`
   * @param message необязательное пояснение для игрока
   */
  constructor(code: string, message?: string) {
    super(message ?? code);
    this.name = 'GameError';
    this.code = code;
  }
}
/**
 * Движок раундов — общий для HTTP-ядра и testkit.
 *
 * Операции движка написаны как генераторы: каждое обращение к кошельку — это `yield` операции
 * (`WalletOp`), в ответ генератор получает баланс после неё. Ошибку кошелька драйвер бросает
 * внутрь генератора. Testkit выполняет генератор синхронно с кошельком в памяти (`runSync`),
 * ядро — асинхронно с HTTP-кошельком (`runAsync`). Логика раунда при этом одна.
 *
 * Сохранность денег: раунд записывается в хранилище **до** списания ставки (признак `pendingBet`)
 * и до выплаты (поле `pendingPayout`). Если ответ кошелька не дошёл, следующая операция с этой игрой
 * досылает ту же транзакцию с тем же `txId` — кошелёк идемпотентен, поэтому повтор безопасен.
 */
import type { GameModule, Rng } from '../sdk/types.ts';
import { PlatformError, messageOf } from '../shared/errors.ts';
import { LIMITS, round2 } from '../shared/money.ts';

/** Операция с кошельком, которую запрашивает движок. Результат — баланс после операции. */
export type WalletOp =
  | { kind: 'balance' }
  | { kind: 'bet' | 'payout'; txId: string; roundId: string; amount: number };

/** Генератор операции движка: отдаёт `WalletOp`, получает баланс, возвращает `T`. */
export type EngineGen<T> = Generator<WalletOp, T, number>;

/** Раунд в хранилище. Параметры и состояние игры хранятся в виде JSON. */
export interface RoundRecord {
  roundId: string;
  gameId: string;
  bet: number;
  params: unknown;
  state: unknown;
  status: 'open' | 'closed';
  /** Выплата закрытого раунда, `null` пока раунд открыт. */
  payout: number | null;
  /** Списание ставки отправлено, но кошелёк его ещё не подтвердил. */
  pendingBet?: boolean;
  /** Игра завершила раунд, но выплата ещё не подтверждена кошельком. */
  pendingPayout: number | null;
  /** Раунд аннулирован (ошибка игры на старте или недосланная ставка): ставка возвращена, `view` = `null`. */
  voided: boolean;
}

/** Ответ раунда — одинаковый у HTTP API и testkit. */
export interface RoundView {
  roundId: string;
  gameId: string;
  bet: number;
  status: 'open' | 'closed';
  view: unknown;
  payout: number | null;
  balance: number;
}

/** Ответ открытия игры. */
export interface OpenResult {
  gameId: string;
  limits: { min: number; max: number };
  balance: number;
  activeRound: RoundView | null;
  /**
   * Раунд, который закрылся при этом открытии: досланная выплата или аннулированный раунд с недосланной ставкой.
   * Поля нет, если ничего не досылалось.
   */
  lastRound?: RoundView;
}

/** Хранилище раундов. Методы синхронные; `get`/`findOpen` возвращают независимую копию. */
export interface RoundStore {
  get(roundId: string): RoundRecord | undefined;
  findOpen(gameId: string): RoundRecord | undefined;
  save(round: RoundRecord): void;
  /** Удаляет раунд, ставку которого кошелёк точно не списал. */
  delete(roundId: string): void;
}

/** Настройки движка. */
export interface EngineOptions {
  games: GameModule[];
  store: RoundStore;
  rng: Rng;
  newRoundId: () => string;
}

/** Движок раундов: лимиты, порядок проверок, вызовы игры, списание и выплата. */
export class RoundEngine {
  /** Подключённые игры по `id`. */
  readonly games: ReadonlyMap<string, GameModule>;
  readonly #store: RoundStore;
  readonly #rng: Rng;
  readonly #newRoundId: () => string;

  /** @param opts игры, хранилище раундов, rng и генератор идентификаторов раундов */
  constructor(opts: EngineOptions) {
    const games = new Map<string, GameModule>();
    for (const g of opts.games) {
      if (!g || typeof g.id !== 'string') throw new TypeError('game module must have a string id');
      if (games.has(g.id)) throw new TypeError(`duplicate game id: ${g.id}`);
      games.set(g.id, g);
    }
    this.games = games;
    this.#store = opts.store;
    this.#rng = opts.rng;
    this.#newRoundId = opts.newRoundId;
  }

  /**
   * Открытие игры: лимиты, баланс и незавершённый раунд.
   * Досылает недошедшие ставку или выплату; закрытый при этом раунд возвращается в `lastRound`.
   */
  *open(gameId: string): EngineGen<OpenResult> {
    this.#game(gameId);
    const last = yield* this.#recover(gameId);
    const round = this.#store.findOpen(gameId);
    const balance: number = yield { kind: 'balance' };
    const result: OpenResult = {
      gameId,
      limits: { min: LIMITS.min, max: LIMITS.max },
      balance,
      activeRound: round ? this.#view(round, balance, true) : null,
    };
    if (last) result.lastRound = this.#view(last, balance, true);
    return result;
  }

  /**
   * Новый раунд. Порядок проверок: игра → лимиты → параметры → досылка недошедших операций → открытый раунд
   * → сохранение раунда → списание → `start`. Кошелёк не вызывается, пока не пройдены все проверки без денег.
   */
  *startRound(gameId: string, bet: unknown, params: unknown): EngineGen<RoundView> {
    const game = this.#game(gameId);
    const amount = checkBet(bet);
    const p = toJson(callGame(() => game.validateParams(params), 'INVALID_PARAMS'));
    yield* this.#recover(gameId);
    if (this.#store.findOpen(gameId)) throw new PlatformError('ROUND_ALREADY_OPEN');

    const roundId = this.#newRoundId();
    const round: RoundRecord = {
      roundId,
      gameId,
      bet: amount,
      params: p,
      state: null,
      status: 'open',
      payout: null,
      pendingBet: true,
      pendingPayout: null,
      voided: false,
    };
    // Раунд записан до списания: если ответ кошелька потеряется, ставку можно будет дослать и вернуть.
    this.#store.save(round);
    let afterBet: number;
    try {
      afterBet = yield { kind: 'bet', txId: `${roundId}:bet`, roundId, amount };
    } catch (e) {
      if (!isUncertain(e)) this.#store.delete(roundId);
      throw e;
    }
    round.pendingBet = false;

    let step: unknown;
    let state: unknown;
    try {
      step = game.start({ bet: amount, params: toJson(p), rng: this.#rng });
      if (isValidStep(step)) state = toJson(step.state);
    } catch (e) {
      // У раунда нет пригодного состояния, продолжать его нельзя: аннулируем и возвращаем ставку.
      round.voided = true;
      yield* this.#settle(round, amount);
      throw internal(`Игра ${game.id} не смогла начать раунд: ${detailOf(e)}`);
    }
    if (!isValidStep(step)) {
      // Ставка уже списана: раунд остаётся открытым с тем, что вернула игра (PL-19, D-023).
      round.state = safeJson((step as { state?: unknown } | null)?.state);
      this.#store.save(round);
      throw internal(`Игра ${game.id} вернула некорректный шаг на старте`);
    }
    return yield* this.#apply(round, step, state, afterBet);
  }

  /** Ход в открытом раунде. При `INVALID_ACTION` и ошибке игры состояние раунда и баланс не меняются. */
  *action(roundId: string, action: unknown): EngineGen<RoundView> {
    const round = this.#store.get(roundId);
    if (!round) throw new PlatformError('ROUND_NOT_FOUND');
    if (round.status === 'closed') throw new PlatformError('ROUND_CLOSED');
    const game = this.games.get(round.gameId);
    if (!game) throw internal(`Игра ${round.gameId} не подключена`);
    if (round.pendingBet === true) {
      // Списание не подтверждено, игра не начиналась: досылаем ставку и аннулируем раунд.
      const closed = yield* this.#retryBet(round);
      throw new PlatformError(closed ? 'ROUND_CLOSED' : 'ROUND_NOT_FOUND');
    }
    if (round.pendingPayout !== null) {
      // Игра уже завершила раунд, ждём только выплату — досылаем её, ходить больше нельзя.
      yield* this.#settle(round, round.pendingPayout);
      throw new PlatformError('ROUND_CLOSED');
    }
    const step = callGame(
      () => game.action({ bet: round.bet, params: round.params, state: round.state, action, rng: this.#rng }),
      'INVALID_ACTION',
    );
    if (!isValidStep(step)) throw internal(`Игра ${game.id} вернула некорректный шаг`);
    const state = toJson(step.state);
    return yield* this.#apply(round, step, state, null);
  }

  /** Досылает недошедшие ставку или выплату открытого раунда игры. Возвращает раунд, если он при этом закрылся. */
  *#recover(gameId: string): EngineGen<RoundRecord | null> {
    const round = this.#store.findOpen(gameId);
    if (!round) return null;
    if (round.pendingBet === true) return yield* this.#retryBet(round);
    if (round.pendingPayout !== null) {
      yield* this.#settle(round, round.pendingPayout);
      return round;
    }
    return null;
  }

  /**
   * Повторяет списание ставки с тем же `txId`. Если кошелёк его провёл — раунд аннулируется со возвратом ставки
   * (игра ещё не начиналась) и возвращается закрытым. Если кошелёк точно отказал — запись удаляется, результат `null`.
   * Если кошелёк снова не ответил — ошибка пробрасывается, раунд остаётся в ожидании.
   */
  *#retryBet(round: RoundRecord): EngineGen<RoundRecord | null> {
    try {
      yield { kind: 'bet', txId: `${round.roundId}:bet`, roundId: round.roundId, amount: round.bet };
    } catch (e) {
      if (isUncertain(e)) throw e;
      this.#store.delete(round.roundId);
      return null;
    }
    round.pendingBet = false;
    round.voided = true;
    yield* this.#settle(round, round.bet);
    return round;
  }

  /** Применяет корректный шаг игры: сохраняет состояние, а на `finished` — выплачивает и закрывает раунд. */
  *#apply(
    round: RoundRecord,
    step: { status: 'continue' } | { status: 'finished'; payout: number },
    state: unknown,
    knownBalance: number | null,
  ): EngineGen<RoundView> {
    round.state = state;
    if (step.status === 'continue') {
      this.#store.save(round);
      const balance: number = knownBalance ?? (yield { kind: 'balance' });
      return this.#view(round, balance, false);
    }
    const balance = yield* this.#settle(round, round2(step.payout));
    return this.#view(round, balance, false);
  }

  /** Выплата `<roundId>:payout` и закрытие раунда. До ответа кошелька раунд сохранён как «ждёт выплаты». */
  *#settle(round: RoundRecord, amount: number): EngineGen<number> {
    round.pendingPayout = amount;
    this.#store.save(round);
    const balance: number = yield { kind: 'payout', txId: `${round.roundId}:payout`, roundId: round.roundId, amount };
    round.status = 'closed';
    round.payout = amount;
    round.pendingPayout = null;
    this.#store.save(round);
    return balance;
  }

  /**
   * Ответ раунда. Если `publicView` игры падает, а раунд уже закрыт или ответ нужен для `open`,
   * отдаётся `view: null`, чтобы сломанное отображение не блокировало игру и не прятало итог раунда.
   */
  #view(round: RoundRecord, balance: number, safe: boolean): RoundView {
    let view: unknown = null;
    if (!round.voided && round.pendingBet !== true) {
      try {
        const game = this.games.get(round.gameId);
        if (!game) throw new Error(`Игра ${round.gameId} не подключена`);
        view = toJson(game.publicView(round.state, round.status === 'closed'));
      } catch (e) {
        const err = internal(`Игра ${round.gameId} не смогла показать раунд ${round.roundId}: ${detailOf(e)}`);
        if (!safe && round.status === 'open') throw err;
        console.error(`${err.code}: ${err.detail}`);
        view = null;
      }
    }
    return { roundId: round.roundId, gameId: round.gameId, bet: round.bet, status: round.status, view, payout: round.payout, balance };
  }

  #game(gameId: unknown): GameModule {
    const game = typeof gameId === 'string' ? this.games.get(gameId) : undefined;
    if (!game) throw new PlatformError('GAME_NOT_FOUND');
    return game;
  }
}

/** Ставка: конечное число, округлённое до центов и попадающее в лимиты. Иначе `BET_OUT_OF_LIMITS`. */
function checkBet(bet: unknown): number {
  if (typeof bet !== 'number' || !Number.isFinite(bet)) throw new PlatformError('BET_OUT_OF_LIMITS');
  const amount = round2(bet);
  if (amount < LIMITS.min || amount > LIMITS.max) throw new PlatformError('BET_OUT_OF_LIMITS');
  return amount;
}

/** `INTERNAL_ERROR` со стандартным сообщением для клиента; подробности — только для серверного лога. */
function internal(detail: string): PlatformError {
  return new PlatformError('INTERNAL_ERROR', undefined, detail);
}

function detailOf(e: unknown): string {
  return e instanceof PlatformError && e.detail !== undefined ? e.detail : messageOf(e);
}

/**
 * Ошибка кошелька, после которой неизвестно, провёл ли он операцию (нет ответа, таймаут, 5xx).
 * Точные отказы (`INSUFFICIENT_FUNDS`, отклонённый запрос) неопределённости не оставляют.
 */
function isUncertain(e: unknown): boolean {
  if (!(e instanceof PlatformError)) return true;
  return e.code === 'WALLET_UNAVAILABLE';
}

/** Вызов игры: ожидаемый код (`INVALID_PARAMS`/`INVALID_ACTION`) пробрасывается, остальное — `INTERNAL_ERROR`. */
function callGame<T>(fn: () => T, expected: 'INVALID_PARAMS' | 'INVALID_ACTION'): T {
  try {
    return fn();
  } catch (e) {
    const code = (e as { code?: unknown } | null)?.code;
    if (code === expected) {
      const msg = e instanceof Error && e.message && e.message !== expected ? e.message : undefined;
      throw new PlatformError(expected, msg);
    }
    throw internal(`Ошибка игры: ${messageOf(e)}`);
  }
}

function isValidStep(step: unknown): step is { status: 'continue'; state: unknown } | { status: 'finished'; state: unknown; payout: number } {
  if (!step || typeof step !== 'object') return false;
  const s = step as { status?: unknown; payout?: unknown };
  if (s.status === 'continue') return true;
  return s.status === 'finished' && typeof s.payout === 'number' && Number.isFinite(s.payout) && s.payout >= 0;
}

/** Копия значения через JSON — так же, как оно переживёт хранение на диске. */
function toJson<T>(value: T): T {
  if (value === undefined) return value;
  try {
    return JSON.parse(JSON.stringify(value)) as T;
  } catch (e) {
    throw internal(`Состояние игры не сериализуется в JSON: ${messageOf(e)}`);
  }
}

function safeJson(value: unknown): unknown {
  try {
    return toJson(value);
  } catch {
    return null;
  }
}

/** Выполняет операцию движка синхронно. `exec` выполняет операцию кошелька или бросает ошибку. */
export function runSync<T>(gen: EngineGen<T>, exec: (op: WalletOp) => number): T {
  let r = gen.next();
  while (!r.done) {
    let balance: number;
    try {
      balance = exec(r.value);
    } catch (e) {
      r = gen.throw(e);
      continue;
    }
    r = gen.next(balance);
  }
  return r.value;
}

/** Выполняет операцию движка асинхронно (кошелёк по HTTP). */
export async function runAsync<T>(gen: EngineGen<T>, exec: (op: WalletOp) => Promise<number>): Promise<T> {
  let r = gen.next();
  while (!r.done) {
    let balance: number;
    try {
      balance = await exec(r.value);
    } catch (e) {
      r = gen.throw(e);
      continue;
    }
    r = gen.next(balance);
  }
  return r.value;
}
/** Хранилища раундов: в памяти (testkit) и на диске (`data/rounds.json`, ядро). */
import fs from 'node:fs';
import path from 'node:path';
import type { RoundRecord, RoundStore } from './engine.ts';

/** Раунды в памяти. Записи хранятся как JSON, поэтому чтение всегда даёт независимую копию. */
export class MemoryRoundStore implements RoundStore {
  /** Раунды по `roundId` в виде JSON-строк. */
  protected readonly rounds = new Map<string, string>();
  readonly #openByGame = new Map<string, string>();

  /** Раунд по идентификатору. */
  get(roundId: string): RoundRecord | undefined {
    const s = this.rounds.get(roundId);
    return s === undefined ? undefined : (JSON.parse(s) as RoundRecord);
  }

  /** Открытый раунд игры, если есть. */
  findOpen(gameId: string): RoundRecord | undefined {
    const id = this.#openByGame.get(gameId);
    return id === undefined ? undefined : this.get(id);
  }

  /** Сохраняет раунд целиком. */
  save(round: RoundRecord): void {
    this.rounds.set(round.roundId, JSON.stringify(round));
    if (round.status === 'open') this.#openByGame.set(round.gameId, round.roundId);
    else if (this.#openByGame.get(round.gameId) === round.roundId) this.#openByGame.delete(round.gameId);
  }

  /** Удаляет раунд (ставку которого кошелёк точно не списал). */
  delete(roundId: string): void {
    const round = this.get(roundId);
    if (!round) return;
    this.rounds.delete(roundId);
    if (this.#openByGame.get(round.gameId) === roundId) this.#openByGame.delete(round.gameId);
  }
}

/** Раунды на диске: файл перечитывается при создании и перезаписывается после каждого изменения. */
export class FileRoundStore extends MemoryRoundStore {
  readonly #file: string;

  /** @param file путь к `rounds.json`; каталог создаётся при необходимости */
  constructor(file: string) {
    super();
    this.#file = file;
    if (fs.existsSync(file)) {
      const data = JSON.parse(fs.readFileSync(file, 'utf8')) as { rounds?: Record<string, RoundRecord> };
      for (const r of Object.values(data.rounds ?? {})) super.save(r);
    }
  }

  /** Сохраняет раунд и записывает файл (через временный файл и rename). */
  override save(round: RoundRecord): void {
    super.save(round);
    this.#write();
  }

  /** Удаляет раунд и записывает файл. */
  override delete(roundId: string): void {
    super.delete(roundId);
    this.#write();
  }

  #write(): void {
    const body = [...this.rounds].map(([id, json]) => `${JSON.stringify(id)}:${json}`).join(',\n');
    fs.mkdirSync(path.dirname(this.#file), { recursive: true });
    const tmp = `${this.#file}.tmp`;
    fs.writeFileSync(tmp, `{"rounds":{\n${body}\n}}\n`);
    fs.renameSync(tmp, this.#file);
  }
}
/** Клиент кошелька для ядра: выполняет операции движка (`WalletOp`) по HTTP через `node:http`. */
import http from 'node:http';
import { PlatformError, messageOf } from '../shared/errors.ts';
import type { WalletOp } from './engine.ts';

const TIMEOUT_MS = 5000;

/**
 * Создаёт исполнитель операций кошелька по адресу `walletUrl`.
 * `402` → `INSUFFICIENT_FUNDS`; сеть, таймаут, `5xx` → `WALLET_UNAVAILABLE`; прочие отказы → `INTERNAL_ERROR`.
 */
export function walletExecutor(walletUrl: string): (op: WalletOp) => Promise<number> {
  return async (op) => {
    const res =
      op.kind === 'balance'
        ? await call(walletUrl, 'GET', '/balance')
        : await call(walletUrl, 'POST', `/${op.kind}`, { txId: op.txId, roundId: op.roundId, amount: op.amount });
    const body = res.body as { balance?: unknown; error?: { code?: unknown } } | undefined;
    if (res.status === 200 && typeof body?.balance === 'number') return body.balance;
    if (res.status === 402) throw new PlatformError('INSUFFICIENT_FUNDS');
    if (res.status >= 500 || res.status === 200) throw new PlatformError('WALLET_UNAVAILABLE');
    throw new PlatformError('INTERNAL_ERROR', `Кошелёк отклонил операцию: ${String(body?.error?.code ?? res.status)}`);
  };
}

function call(base: string, method: string, urlPath: string, body?: unknown): Promise<{ status: number; body: unknown }> {
  const payload = body === undefined ? undefined : JSON.stringify(body);
  return new Promise((resolve, reject) => {
    const fail = (e: unknown): void => reject(new PlatformError('WALLET_UNAVAILABLE', `Кошелёк недоступен: ${messageOf(e)}`));
    const req = http.request(
      new URL(urlPath, base),
      {
        method,
        timeout: TIMEOUT_MS,
        headers: payload === undefined ? {} : { 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload) },
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on('data', (c: Buffer) => chunks.push(c));
        res.on('error', fail);
        res.on('end', () => {
          let parsed: unknown;
          try {
            parsed = JSON.parse(Buffer.concat(chunks).toString('utf8'));
          } catch {
            parsed = undefined;
          }
          resolve({ status: res.statusCode ?? 0, body: parsed });
        });
      },
    );
    req.on('timeout', () => req.destroy(new Error('timeout')));
    req.on('error', fail);
    if (payload !== undefined) req.write(payload);
    req.end();
  });
}
/** Ошибки платформы: код, HTTP-статус и сообщение для игрока. */

/** HTTP-статус для каждого кода ошибки платформы. Неизвестный код — 500. */
export const ERROR_STATUS: Readonly<Record<string, number>> = Object.freeze({
  BET_OUT_OF_LIMITS: 400,
  INVALID_PARAMS: 400,
  INVALID_ACTION: 400,
  INVALID_REQUEST: 400,
  INSUFFICIENT_FUNDS: 402,
  FORBIDDEN: 403,
  UNSUPPORTED_MEDIA_TYPE: 415,
  GAME_NOT_FOUND: 404,
  ROUND_NOT_FOUND: 404,
  NOT_FOUND: 404,
  ROUND_ALREADY_OPEN: 409,
  ROUND_CLOSED: 409,
  INTERNAL_ERROR: 500,
  WALLET_UNAVAILABLE: 502,
});

const DEFAULT_MESSAGES: Readonly<Record<string, string>> = {
  BET_OUT_OF_LIMITS: 'Ставка должна быть от $1 до $10',
  INVALID_PARAMS: 'Неверные параметры раунда',
  INVALID_ACTION: 'Это действие сейчас недоступно',
  INVALID_REQUEST: 'Некорректный запрос',
  INSUFFICIENT_FUNDS: 'Недостаточно средств',
  FORBIDDEN: 'Запрос с чужого сайта отклонён',
  UNSUPPORTED_MEDIA_TYPE: 'Тело запроса должно быть application/json',
  GAME_NOT_FOUND: 'Игра не найдена',
  ROUND_NOT_FOUND: 'Раунд не найден',
  NOT_FOUND: 'Не найдено',
  ROUND_ALREADY_OPEN: 'В этой игре уже есть незавершённый раунд',
  ROUND_CLOSED: 'Раунд уже завершён',
  INTERNAL_ERROR: 'Внутренняя ошибка',
  WALLET_UNAVAILABLE: 'Кошелёк временно недоступен',
};

/** Ошибка платформы. Testkit бросает её как есть, HTTP API отдаёт как `{ error: { code, message } }`. */
export class PlatformError extends Error {
  /** Код ошибки, например `BET_OUT_OF_LIMITS`. */
  code: string;
  /** HTTP-статус ответа. */
  status: number;
  /** Подробности для серверного лога. Клиенту не отдаются: в них может быть скрытое состояние игры. */
  detail?: string;

  /**
   * @param code код ошибки
   * @param message сообщение; по умолчанию — стандартный текст для кода
   * @param detail подробности только для серверного лога
   */
  constructor(code: string, message?: string, detail?: string) {
    super(message ?? DEFAULT_MESSAGES[code] ?? code);
    this.name = 'PlatformError';
    this.code = code;
    this.status = ERROR_STATUS[code] ?? 500;
    if (detail !== undefined) this.detail = detail;
  }
}

/** Текст ошибки любого типа для логов и сообщений. */
export function messageOf(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}
/** Мелкие помощники для HTTP-сервисов на `node:http`. */
import http from 'node:http';
import { PlatformError } from './errors.ts';

/** Запущенный HTTP-сервис. */
export interface RunningServer {
  /** Фактический адрес, например `http://127.0.0.1:4000`. */
  url: string;
  /** Останавливает сервис и закрывает соединения. */
  close(): Promise<void>;
}

const MAX_BODY = 1024 * 1024;

/** Читает JSON-тело запроса. Пустое тело — `undefined`, битый JSON — `PlatformError('INVALID_REQUEST')`. */
export async function readJson(req: http.IncomingMessage): Promise<unknown> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    size += (chunk as Buffer).length;
    if (size > MAX_BODY) throw new PlatformError('INVALID_REQUEST', 'Слишком большое тело запроса');
    chunks.push(chunk as Buffer);
  }
  const text = Buffer.concat(chunks).toString('utf8').trim();
  if (!text) return undefined;
  try {
    return JSON.parse(text);
  } catch {
    throw new PlatformError('INVALID_REQUEST', 'Тело запроса — не JSON');
  }
}

/** Отправляет JSON-ответ. */
export function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
  const text = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'content-length': Buffer.byteLength(text), 'cache-control': 'no-store' });
  res.end(text);
}

/** Отправляет ошибку в формате `{ error: { code, message } }`; неизвестная ошибка — 500 `INTERNAL_ERROR`. */
export function sendError(res: http.ServerResponse, e: unknown, extra: Record<string, unknown> = {}): void {
  const err = e instanceof PlatformError ? e : new PlatformError('INTERNAL_ERROR');
  if (!(e instanceof PlatformError)) console.error(e);
  else if (err.detail !== undefined) console.error(`${err.code}: ${err.detail}`);
  sendJson(res, err.status, { error: { code: err.code, message: err.message }, ...extra });
}

/** Запускает сервер на `host:port` (`port: 0` — свободный порт) и возвращает `RunningServer`. */
export function listen(server: http.Server, port: number, host: string): Promise<RunningServer> {
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => {
      server.off('error', reject);
      const addr = server.address();
      const actual = typeof addr === 'object' && addr ? addr.port : port;
      const urlHost = host.includes(':') ? `[${host}]` : host;
      resolve({
        url: `http://${urlHost}:${actual}`,
        close: () =>
          new Promise<void>((done) => {
            server.close(() => done());
            server.closeAllConnections();
          }),
      });
    });
  });
}
/** Деньги и лимиты ставки. Суммы — числа в долларах, округлённые до центов. */

/** Лимиты ставки платформы, в долларах. */
export const LIMITS: Readonly<{ min: number; max: number }> = Object.freeze({ min: 1, max: 10 });

/**
 * Округляет сумму до центов, половина цента — вверх (1.955 → 1.96, 1.006 → 1.01).
 * Округление идёт по десятичной записи числа, поэтому не страдает от двоичной погрешности
 * (`Math.round(1.955 * 100)` дал бы 195).
 */
export function round2(x: number): number {
  if (!Number.isFinite(x)) return x;
  const abs = Math.abs(x);
  const s = String(abs);
  const r = s.includes('e') ? Math.round(abs * 100) / 100 : Number(`${Math.round(Number(`${s}e2`))}e-2`);
  if (r === 0) return 0;
  return x < 0 ? -r : r;
}

