110	      if (parts[0] === 'api') return await handleApi(req, res, parts.slice(1));
111	      if (req.method !== 'GET' && req.method !== 'HEAD') throw new PlatformError('NOT_FOUND');
112	      if (url.pathname === '/' || url.pathname === '/index.html') return sendFile(req, res, SHELL_FILE);
113	      if (url.pathname === '/sdk.js') return sendFile(req, res, SDK_FILE);
114	      if (parts[0] === 'games' && parts[1]) {
115	        const game = byId.get(parts[1]);
116	        if (!game) throw new PlatformError('GAME_NOT_FOUND');
117	        if (parts.length === 2 && !url.pathname.endsWith('/')) {
118	          res.writeHead(301, { location: `/games/${encodeURIComponent(parts[1])}/` });
119	          return void res.end();
120	        }
121	        const uiDir = path.dirname(game.uiFile);
122	        const rest = parts.slice(2);
123	        const file = rest.length === 0 ? game.uiFile : path.resolve(uiDir, ...rest);
124	        if (file !== game.uiFile && !file.startsWith(uiDir + path.sep)) throw new PlatformError('NOT_FOUND');
125	        return sendFile(req, res, file);
126	      }
127	      throw new PlatformError('NOT_FOUND');
128	    } catch (e) {
129	      if (e instanceof URIError) return sendError(res, new PlatformError('INVALID_REQUEST'));
130	      sendError(res, e);
131	    }
132	  });
133	
134	  return listen(server, opts.port, opts.host ?? '127.0.0.1');
135	}
