  1	/**
  2	 * Кошелёк партнёра — отдельный HTTP-сервис, который владеет балансом игрока `player-1`.
  3	 *
  4	 * - `GET /balance` → `{ balance }`
  5	 * - `POST /bet { txId, roundId, amount }` → `{ balance }` или `402 INSUFFICIENT_FUNDS`
  6	 * - `POST /payout { txId, roundId, amount }` → `{ balance }`
  7	 *
  8	 * Повтор `txId` с теми же данными возвращает сохранённый ответ, с другими — `409 TX_CONFLICT`.
  9	 * Баланс и журнал хранятся в `<dataDir>/wallet.json`.
 10	 */
 11	import fs from 'node:fs';
 12	import http from 'node:http';
 13	import path from 'node:path';
 14	import { PlatformError } from '../shared/errors.ts';
 15	import { listen, readJson, sendError, sendJson, type RunningServer } from '../shared/http.ts';
 16	import { round2 } from '../shared/money.ts';
 17	
 18	export type { RunningServer };
 19	
 20	/** Начальный баланс игрока. */
 21	export const START_BALANCE = 100;
 22	/** Единственный игрок. */
 23	export const PLAYER_ID = 'player-1';
 24	
 25	/** Запись журнала транзакций кошелька. */
 26	export interface WalletTx {
 27	  type: 'bet' | 'payout';
 28	  roundId: string;
 29	  amount: number;
 30	  /** Сумма из запроса до округления — по ней повтор `txId` сравнивается с исходным. */
 31	  requestedAmount?: number;
 32	  /** Сохранённый ответ: повтор `txId` отдаёт его без изменений. */
 33	  status: number;
 34	  body: unknown;
 35	}
 36	
 37	/** Содержимое `wallet.json`. */
 38	export interface WalletState {
 39	  player: string;
 40	  balance: number;
 41	  transactions: Record<string, WalletTx>;
 42	}
 43	
 44	/** Настройки запуска кошелька. */
 45	export interface WalletOptions {
 46	  /** Порт; 0 — свободный. */
 47	  port: number;
 48	  /** Каталог данных, где лежит `wallet.json`. */
 49	  dataDir: string;
 50	  /** Адрес прослушивания; по умолчанию `127.0.0.1`. */
 51	  host?: string;
 52	}
 53	
 54	/** Запускает HTTP-сервис кошелька. */
 55	export async function startWallet(opts: WalletOptions): Promise<RunningServer> {
 56	  const file = path.join(opts.dataDir, 'wallet.json');
 57	  const state = loadState(file);
 58	
 59	  const persist = (next: WalletState): void => {
 60	    fs.mkdirSync(opts.dataDir, { recursive: true });
 61	    const tmp = `${file}.tmp`;
 62	    fs.writeFileSync(tmp, `${JSON.stringify(next, null, 1)}\n`);
 63	    fs.renameSync(tmp, file);
 64	  };
 65	
 66	  const transact = (type: 'bet' | 'payout', input: unknown): { status: number; body: unknown } => {
 67	    const { txId, roundId, amount } = (input ?? {}) as { txId?: unknown; roundId?: unknown; amount?: unknown };
 68	    if (typeof txId !== 'string' || !txId || typeof roundId !== 'string' || !roundId) {
 69	      throw new PlatformError('INVALID_REQUEST', 'Нужны строковые txId и roundId');
 70	    }
 71	    const value = typeof amount === 'number' && Number.isFinite(amount) ? round2(amount) : Number.NaN;
 72	    if (!Number.isFinite(value) || (type === 'bet' ? value <= 0 : value < 0)) {
 73	      return { status: 400, body: { error: { code: 'INVALID_AMOUNT', message: 'Некорректная сумма' } } };
 74	    }
 75	
 76	    const requested = amount as number;
 77	    const prev = state.transactions[txId];
 78	    if (prev) {
 79	      // Сравнивается сумма из запроса до округления: 2.5 и 2.504 — разные данные (у старых записей — округлённая).
 80	      const prevRequested = prev.requestedAmount ?? prev.amount;
 81	      if (prev.type === type && prev.roundId === roundId && prevRequested === requested) return { status: prev.status, body: prev.body };
 82	      return { status: 409, body: { error: { code: 'TX_CONFLICT', message: 'txId уже использован с другими данными' } } };
 83	    }
 84	
 85	    let balance = state.balance;
 86	    let result: { status: number; body: unknown };
 87	    if (type === 'bet' && value > balance) {
 88	      result = { status: 402, body: { error: { code: 'INSUFFICIENT_FUNDS', message: 'Недостаточно средств' }, balance } };
 89	    } else {
 90	      balance = round2(type === 'bet' ? balance - value : balance + value);
 91	      result = { status: 200, body: { balance } };
 92	    }
 93	    const tx: WalletTx = { type, roundId, amount: value, requestedAmount: requested, status: result.status, body: result.body };
 94	    // Сначала диск, потом память: если запись упадёт, баланс и журнал в памяти останутся прежними.
 95	    persist({ ...state, balance, transactions: { ...state.transactions, [txId]: tx } });
 96	    state.balance = balance;
 97	    state.transactions[txId] = tx;
 98	    return result;
 99	  };
100	
101	  const server = http.createServer(async (req, res) => {
102	    try {
103	      const url = new URL(req.url ?? '/', 'http://wallet');
104	      if (req.method === 'GET' && url.pathname === '/balance') return sendJson(res, 200, { balance: state.balance });
105	      if (req.method === 'POST' && (url.pathname === '/bet' || url.pathname === '/payout')) {
106	        const body = await readJson(req);
107	        const r = transact(url.pathname === '/bet' ? 'bet' : 'payout', body);
108	        return sendJson(res, r.status, r.body);
109	      }
110	      throw new PlatformError('NOT_FOUND');
111	    } catch (e) {
112	      sendError(res, e);
113	    }
114	  });
115	
116	  return listen(server, opts.port, opts.host ?? '127.0.0.1');
117	}
118	
119	function loadState(file: string): WalletState {
120	  if (!fs.existsSync(file)) return { player: PLAYER_ID, balance: START_BALANCE, transactions: {} };
121	  // Битый файл — ошибка запуска: молча сбросить баланс игрока нельзя.
122	  const data = JSON.parse(fs.readFileSync(file, 'utf8')) as Partial<WalletState>;
123	  if (typeof data.balance !== 'number' || !Number.isFinite(data.balance)) throw new Error(`${file}: некорректный баланс`);
124	  return { player: PLAYER_ID, balance: data.balance, transactions: data.transactions ?? {} };
125	}
