 51	
 52	/** Криптостойкий генератор на `node:crypto`: равномерное число в [0, 1) с шагом 2⁻⁴⁸. */
 53	export const cryptoRng: Rng = {
 54	  next: () => crypto.randomBytes(6).readUIntBE(0, 6) / 2 ** 48,
 55	};
 56	
 57	/** Запускает ядро: загружает игры и раунды, поднимает HTTP-сервис. */
 58	export async function startCore(opts: CoreOptions): Promise<RunningServer> {
 59	  const games = await loadGames(opts.gamesDir);
 60	  const byId = new Map<string, LoadedGame>(games.map((g) => [g.manifest.id, g]));
 61	  const engine = new RoundEngine({
 62	    games: games.map((g) => g.module),
 63	    store: new FileRoundStore(path.join(opts.dataDir, 'rounds.json')),
 64	    rng: opts.rng ?? cryptoRng,
 65	    newRoundId: () => crypto.randomUUID(),
 66	  });
 67	  const exec = walletExecutor(opts.walletUrl);
 68	
 69	  // Операции движка выполняются строго по очереди: проверка «нет открытого раунда» и списание атомарны.
 70	  let queue: Promise<unknown> = Promise.resolve();
 71	  const run = <T>(gen: () => EngineGen<T>): Promise<T> => {
 72	    const p = queue.then(() => runAsync(gen(), exec));
 73	    queue = p.catch(() => undefined);
 74	    return p;
 75	  };
 76	
 77	  const handleApi = async (req: http.IncomingMessage, res: http.ServerResponse, parts: string[]): Promise<void> => {
 78	    const method = req.method ?? 'GET';
 79	    // GET /api/games
 80	    if (parts.length === 1 && parts[0] === 'games' && method === 'GET') {
 81	      return sendJson(res, 200, games.map((g) => ({ id: g.manifest.id, title: g.manifest.title })));
 82	    }
 83	    // GET /api/balance — для оболочки
 84	    if (parts.length === 1 && parts[0] === 'balance' && method === 'GET') {
 85	      return sendJson(res, 200, { balance: await exec({ kind: 'balance' }) });
 86	    }
 87	    if (method === 'POST' && parts.length === 3) {
 88	      checkSameOrigin(req);
 89	      const [kind, id, verb] = parts as [string, string, string];
 90	      if (kind === 'games' && verb === 'open') {
 91	        await readJson(req);
 92	        return sendJson(res, 200, await run(() => engine.open(id)));
 93	      }
 94	      if (kind === 'games' && verb === 'rounds') {
 95	        const body = ((await readJson(req)) ?? {}) as { bet?: unknown; params?: unknown };
 96	        return sendJson(res, 200, await run(() => engine.startRound(id, body.bet, body.params)));
 97	      }
 98	      if (kind === 'rounds' && verb === 'actions') {
 99	        const body = ((await readJson(req)) ?? {}) as { action?: unknown };
100	        return sendJson(res, 200, await run(() => engine.action(id, body.action)));
101	      }
102	    }
103	    throw new PlatformError('NOT_FOUND');
104	  };
105	
106	  const server = http.createServer(async (req, res) => {
107	    try {
108	      const url = new URL(req.url ?? '/', 'http://core');
109	      const parts = url.pathname.split('/').filter(Boolean).map((p) => decodeURIComponent(p));
110	      if (parts[0] === 'api') return await handleApi(req, res, parts.slice(1));
111	      if (req.method !== 'GET' && req.method !== 'HEAD') throw new PlatformError('NOT_FOUND');
112	      if (url.pathname === '/' || url.pathname === '/index.html') return sendFile(req, res, SHELL_FILE);
113	      if (url.pathname === '/sdk.js') return sendFile(req, res, SDK_FILE);
114	      if (parts[0] === 'games' && parts[1]) {
115	        const game = byId.get(parts[1]);
116	        if (!game) throw new PlatformError('GAME_NOT_FOUND');
117	        if (parts.length === 2 && !url.pathname.endsWith('/')) {
118	          res.writeHead(301, { location: `/games/${encodeURIComponent(parts[1])}/` });
119	          return void res.end();
120	        }
121	        const uiDir = path.dirname(game.uiFile);
122	        const rest = parts.slice(2);
123	        const file = rest.length === 0 ? game.uiFile : path.resolve(uiDir, ...rest);
124	        if (file !== game.uiFile && !file.startsWith(uiDir + path.sep)) throw new PlatformError('NOT_FOUND');
125	        return sendFile(req, res, file);
126	      }
127	      throw new PlatformError('NOT_FOUND');
128	    } catch (e) {
129	      if (e instanceof URIError) return sendError(res, new PlatformError('INVALID_REQUEST'));
130	      sendError(res, e);
131	    }
132	  });
133	
134	  return listen(server, opts.port, opts.host ?? '127.0.0.1');
135	}
136	
137	/**
138	 * Защита API от запросов со сторонних сайтов (CSRF): заголовок `Origin`, если он есть, должен совпадать с `Host`,
139	 * а непустое тело — иметь тип `application/json` (такой запрос браузер не отправит с чужого сайта без preflight).
140	 */
141	function checkSameOrigin(req: http.IncomingMessage): void {
142	  const origin = req.headers.origin;
143	  if (origin !== undefined) {
144	    let host: string | undefined;
145	    try {
146	      host = new URL(origin).host;
147	    } catch {
148	      host = undefined;
149	    }
150	    if (!host || host !== req.headers.host) throw new PlatformError('FORBIDDEN');
151	  }
152	  const length = Number(req.headers['content-length'] ?? 0);
153	  const hasBody = req.headers['transfer-encoding'] !== undefined || length > 0;
154	  const type = String(req.headers['content-type'] ?? '').split(';')[0]?.trim().toLowerCase();
155	  if (hasBody && type !== 'application/json') throw new PlatformError('UNSUPPORTED_MEDIA_TYPE');
156	}
157	
158	function sendFile(req: http.IncomingMessage, res: http.ServerResponse, file: string): void {
159	  let data: Buffer;
160	  try {
161	    if (!fs.statSync(file).isFile()) throw new Error('not a file');
162	    data = fs.readFileSync(file);
163	  } catch {
164	    throw new PlatformError('NOT_FOUND');
165	  }
166	  const type = CONTENT_TYPES[path.extname(file).toLowerCase()] ?? 'application/octet-stream';
167	  res.writeHead(200, { 'content-type': type, 'content-length': data.length, 'cache-control': 'no-cache' });
168	  res.end(req.method === 'HEAD' ? undefined : data);
169	}
  1	/** Автоподключение игр: находит `<gamesDir>/*\/manifest.json` и загружает серверные модули. */
  2	import fs from 'node:fs';
  3	import path from 'node:path';
  4	import { pathToFileURL } from 'node:url';
  5	import type { GameModule } from '../sdk/types.ts';
  6	import { messageOf } from '../shared/errors.ts';
  7	
  8	/** Манифест игры `{ id, title, server, ui }`. */
  9	export interface GameManifest {
 10	  id: string;
 11	  title: string;
 12	  server: string;
 13	  ui: string;
 14	}
 15	
 16	/** Подключённая игра: манифест, серверный модуль и абсолютный путь к интерфейсу. */
 17	export interface LoadedGame {
 18	  manifest: GameManifest;
 19	  module: GameModule;
 20	  /** Каталог игры. */
 21	  dir: string;
 22	  /** Абсолютный путь к файлу интерфейса (`ui` из манифеста). */
 23	  uiFile: string;
 24	}
 25	
 26	const ID_RE = /^[a-z0-9][a-z0-9_-]*$/;
 27	
 28	/**
 29	 * Загружает игры из каталога, отсортированные по `id`. Некорректный манифест или модуль
 30	 * не роняет загрузку: игра пропускается с предупреждением в лог.
 31	 */
 32	export async function loadGames(gamesDir: string, log: (msg: string) => void = console.warn): Promise<LoadedGame[]> {
 33	  if (!fs.existsSync(gamesDir)) return [];
 34	  const loaded = new Map<string, LoadedGame>();
 35	  const dirs = fs
 36	    .readdirSync(gamesDir, { withFileTypes: true })
 37	    .filter((d) => d.isDirectory())
 38	    .map((d) => d.name)
 39	    .sort();
 40	  for (const name of dirs) {
 41	    const dir = path.join(gamesDir, name);
 42	    const manifestFile = path.join(dir, 'manifest.json');
 43	    if (!fs.existsSync(manifestFile)) continue;
 44	    try {
 45	      const manifest = parseManifest(fs.readFileSync(manifestFile, 'utf8'));
 46	      if (loaded.has(manifest.id)) throw new Error(`игра с id "${manifest.id}" уже подключена`);
 47	      const serverFile = inside(dir, manifest.server);
 48	      const uiFile = inside(dir, manifest.ui);
 49	      const mod = (await import(pathToFileURL(serverFile).href)) as { default?: unknown };
 50	      const game = checkModule(mod.default, manifest.id);
 51	      loaded.set(manifest.id, { manifest, module: game, dir, uiFile });
 52	    } catch (e) {
 53	      log(`[core] игра в ${dir} пропущена: ${messageOf(e)}`);
 54	    }
 55	  }
 56	  return [...loaded.values()].sort((a, b) => (a.manifest.id < b.manifest.id ? -1 : a.manifest.id > b.manifest.id ? 1 : 0));
 57	}
 58	
 59	function parseManifest(text: string): GameManifest {
 60	  const m = JSON.parse(text) as Partial<Record<keyof GameManifest, unknown>> | null;
 61	  if (!m || typeof m !== 'object') throw new Error('манифест не объект');
 62	  for (const key of ['id', 'title', 'server', 'ui'] as const) {
 63	    if (typeof m[key] !== 'string' || !m[key]) throw new Error(`в манифесте нет строки "${key}"`);
 64	  }
 65	  if (!ID_RE.test(m.id as string)) throw new Error(`недопустимый id "${String(m.id)}"`);
 66	  return { id: m.id as string, title: m.title as string, server: m.server as string, ui: m.ui as string };
 67	}
 68	
 69	function inside(dir: string, rel: string): string {
 70	  const full = path.resolve(dir, rel);
 71	  if (!full.startsWith(dir + path.sep)) throw new Error(`путь "${rel}" выходит за каталог игры`);
 72	  if (!fs.existsSync(full)) throw new Error(`файл "${rel}" не найден`);
 73	  return full;
 74	}
 75	
 76	function checkModule(mod: unknown, id: string): GameModule {
 77	  const g = mod as Partial<GameModule> | undefined;
 78	  if (!g || typeof g !== 'object') throw new Error('серверный модуль не экспортирует default');
 79	  for (const fn of ['validateParams', 'start', 'action', 'publicView'] as const) {
 80	    if (typeof g[fn] !== 'function') throw new Error(`в модуле нет функции ${fn}`);
 81	  }
 82	  if (g.id !== id) throw new Error(`id модуля "${String(g.id)}" не совпадает с манифестом "${id}"`);
 83	  return g as GameModule;
 84	}
  1	/**
  2	 * Тестовый набор для игр: тот же движок раундов, что у ядра, но в памяти — без HTTP и диска.
  3	 * Все методы синхронные; ответы такие же, как у HTTP API, ошибки бросаются как `PlatformError`.
  4	 */
  5	import type { GameModule, Rng } from '../sdk/types.ts';
  6	import { RoundEngine, runSync, type OpenResult, type RoundView, type WalletOp } from '../core/engine.ts';
  7	import { MemoryRoundStore } from '../core/store.ts';
  8	import { PlatformError } from '../shared/errors.ts';
  9	import { round2 } from '../shared/money.ts';
 10	
 11	export { PlatformError };
 12	export type { OpenResult, RoundView };
 13	
 14	/** Запись журнала транзакций тестовой платформы. */
 15	export interface Tx {
 16	  txId: string;
 17	  type: 'bet' | 'payout';
 18	  roundId: string;
 19	  amount: number;
 20	  balanceAfter: number;
 21	}
 22	
 23	/** Тестовая платформа. */
 24	export interface TestPlatform {
 25	  /** Открытие игры: лимиты, баланс, незавершённый раунд. */
 26	  open(gameId: string): OpenResult;
 27	  /** Новый раунд со ставкой `bet` и параметрами игры. */
 28	  startRound(gameId: string, bet: unknown, params?: unknown): RoundView;
 29	  /** Ход в раунде. */
 30	  action(roundId: string, action: unknown): RoundView;
 31	  /** Текущий баланс игрока. */
 32	  balance(): number;
 33	  /** Проведённые операции кошелька в порядке выполнения (отклонённые не попадают). */
 34	  transactions(): Tx[];
 35	}
 36	
 37	/** Настройки тестовой платформы. */
 38	export interface TestPlatformOptions {
 39	  /** Серверные модули игр. */
 40	  games: GameModule[];
 41	  /** Генератор случайных чисел; по умолчанию `seededRng(1)`. */
 42	  rng?: Rng;
 43	  /** Стартовый баланс; по умолчанию 100. */
 44	  startBalance?: number;
 45	}
 46	
 47	/** Создаёт платформу в памяти с кошельком и движком раундов. */
 48	export function createTestPlatform(opts: TestPlatformOptions): TestPlatform {
 49	  let balance = round2(opts.startBalance ?? 100);
 50	  const txs: Tx[] = [];
 51	  let seq = 0;
 52	  const engine = new RoundEngine({
 53	    games: opts.games,
 54	    store: new MemoryRoundStore(),
 55	    rng: opts.rng ?? seededRng(1),
 56	    newRoundId: () => `round-${++seq}`,
 57	  });
 58	
 59	  const exec = (op: WalletOp): number => {
 60	    if (op.kind === 'balance') return balance;
 61	    if (op.kind === 'bet') {
 62	      if (op.amount > balance) throw new PlatformError('INSUFFICIENT_FUNDS');
 63	      balance = round2(balance - op.amount);
 64	    } else {
 65	      balance = round2(balance + op.amount);
 66	    }
 67	    txs.push({ txId: op.txId, type: op.kind, roundId: op.roundId, amount: op.amount, balanceAfter: balance });
 68	    return balance;
 69	  };
 70	
 71	  return {
 72	    open: (gameId) => runSync(engine.open(gameId), exec),
 73	    startRound: (gameId, bet, params) => runSync(engine.startRound(gameId, bet, params), exec),
 74	    action: (roundId, action) => runSync(engine.action(roundId, action), exec),
 75	    balance: () => balance,
 76	    transactions: () => txs.map((t) => ({ ...t })),
 77	  };
 78	}
 79	
 80	/** Генератор, который отдаёт заданные числа по очереди. Когда они кончились — `Error('fixedRng exhausted')`. */
 81	export function fixedRng(values: number[]): Rng {
 82	  for (const v of values) {
 83	    if (typeof v !== 'number' || !Number.isFinite(v) || v < 0 || v >= 1) {
 84	      throw new RangeError(`fixedRng: значение ${v} вне [0, 1)`);
 85	    }
 86	  }
 87	  const queue = [...values];
 88	  let i = 0;
 89	  return {
 90	    next(): number {
 91	      if (i >= queue.length) throw new Error('fixedRng exhausted');
 92	      return queue[i++] as number;
 93	    },
 94	  };
 95	}
 96	
 97	/** Воспроизводимый генератор (mulberry32): одинаковый `seed` — одинаковая последовательность в [0, 1). */
 98	export function seededRng(seed: number): Rng {
 99	  let a = Math.trunc(seed) >>> 0;
100	  return {
101	    next(): number {
102	      a = (a + 0x6d2b79f5) >>> 0;
103	      let t = a;
104	      t = Math.imul(t ^ (t >>> 15), t | 1);
105	      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
106	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
107	    },
108	  };
109	}
  1	/**
  2	 * Запуск приложения: `pnpm start` поднимает кошелёк (4001) и ядро (4000).
  3	 * Данные — в `data/`, игры — в `games/` (относительно корня репозитория).
  4	 */
  5	import path from 'node:path';
  6	import { fileURLToPath } from 'node:url';
  7	import { startCore } from './core/index.ts';
  8	import { startWallet } from './wallet/index.ts';
  9	
 10	const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
 11	const dataDir = path.join(root, 'data');
 12	const gamesDir = path.join(root, 'games');
 13	
 14	const wallet = await startWallet({ port: 4001, dataDir });
 15	const core = await startCore({ port: 4000, dataDir, gamesDir, walletUrl: wallet.url });
 16	
 17	console.log(`Кошелёк: ${wallet.url}`);
 18	console.log(`Приложение: http://localhost:4000 (${core.url})`);
 19	
 20	const stop = async (): Promise<void> => {
 21	  await core.close();
 22	  await wallet.close();
 23	  process.exit(0);
 24	};
 25	process.once('SIGINT', stop);
 26	process.once('SIGTERM', stop);

